-- erkhet_ledger_copy:data:begin
-- The other side of every copy posts by the key ERKHET_CLEARING (the journal list names no counter
-- account). fin-bridge's boot adds the key too; here it must exist before its rule.
INSERT INTO fin.posting_keys (company_id, code, required_control, requires_tax_code)
  SELECT c.id, 'ERKHET_CLEARING', 'NONE', false FROM fin.companies c
  ON CONFLICT DO NOTHING;
--> statement-breakpoint
-- The key's account, for every company whose chart is not empty (an empty chart takes the account
-- from the chart template at the next boot). A key that already has a rule is left alone: the
-- account is found by the key, never by its code. Otherwise the account «Эрхэтээс хуулсан гүйлгээний
-- тохируулга» is created on 390102, or, when that code belongs to another account, on the next free
-- code up to 390199; an account of another name is never reused. Without a free code the migration
-- fails rather than post the copies' other side on a foreign account.
DO $$
DECLARE
  company record;
  clearing_name CONSTANT text := 'Эрхэтээс хуулсан гүйлгээний тохируулга';
  found_id bigint;
  candidate text;
  n integer;
BEGIN
  FOR company IN
    SELECT c.id, c.code FROM fin.companies c
     WHERE EXISTS (SELECT 1 FROM fin.accounts a WHERE a.company_id = c.id)
       AND NOT EXISTS (SELECT 1 FROM fin.posting_rules r
                        WHERE r.company_id = c.id AND r.posting_key = 'ERKHET_CLEARING')
     ORDER BY c.id
  LOOP
    found_id := NULL;
    FOR n IN 390102..390199 LOOP
      candidate := n::text;
      SELECT a.id INTO found_id FROM fin.accounts a
       WHERE a.company_id = company.id AND a.code = candidate
         AND a.name = clearing_name AND a.kind = 'EQUITY' AND a.control = 'NONE';
      EXIT WHEN found_id IS NOT NULL;
      IF NOT EXISTS (SELECT 1 FROM fin.accounts a
                      WHERE a.company_id = company.id AND a.code = candidate) THEN
        INSERT INTO fin.accounts (company_id, code, name, kind, normal_side, control)
          VALUES (company.id, candidate, clearing_name, 'EQUITY', 'CREDIT', 'NONE')
          RETURNING id INTO found_id;
        IF candidate <> '390102' THEN
          RAISE NOTICE 'erkhet_ledger_copy: 390102 is taken in company %, the clearing account is %',
            company.code, candidate;
        END IF;
        EXIT;
      END IF;
    END LOOP;
    IF found_id IS NULL THEN
      RAISE EXCEPTION 'erkhet_ledger_copy: no free account code 390102..390199 in company % for the clearing account of the Erkhet copies', company.code;
    END IF;
    INSERT INTO fin.posting_rules (company_id, posting_key, account_id, effective_from)
      VALUES (company.id, 'ERKHET_CLEARING', found_id, DATE '2000-01-01');
  END LOOP;
END $$;
-- erkhet_ledger_copy:data:end
